import {resetOrbit} from './camera-controls.mjs';
// Optional test harness. It feeds world-space joystick intent into the real controller.
export function installCandidateTest({world,state,motion,setInspect,resetJoy}){
 const panel=document.createElement('section');panel.id='candidateValidation';panel.style.cssText='position:fixed;top:110px;left:14px;z-index:44;width:190px;padding:12px;background:#122c3ded;color:#f2f6f8;border-radius:6px;font:11px Arial;line-height:1.6';panel.innerHTML='<b style="color:#ffb36a">HOTFIX 003 · GLB ARTLIST</b><div id="candidateStatus">Idle · Walk · Turn · Stop<br>29.998 triángulos · 21 huesos</div><button id="runCandidateTest" style="background:#f99a42;color:#122c3d;padding:8px;border-radius:4px;margin-top:8px;font-weight:bold">Grabar prueba de movimiento</button><button id="runCandidateClose" style="background:#d8e7ec;color:#122c3d;padding:6px;border-radius:4px;margin-top:5px">Grabar toma cercana</button><a id="candidateVideo" download="DrillRun_Hotfix003_Caminata.webm" hidden style="color:#6de5cc;display:none;margin-top:8px">Descargar video</a><details hidden id="candidateMeasurements"><summary>Mediciones</summary><pre id="candidateReport" style="white-space:pre-wrap;font-size:9px;max-height:110px;overflow:auto"></pre></details>';document.body.append(panel);
 const status=panel.querySelector('#candidateStatus'),button=panel.querySelector('button'),link=panel.querySelector('a');let closeView=false,previousAngle='three';let active=false,time=0,frames=0,stages=[],lastStage='',recorder=null,chunks=[],url=null,started=0,lastPos=null;const visits={};
 function begin(close=false){resetOrbit(world.orbit);previousAngle=world.inspectAngle;closeView=close;setInspect(close,'worker');if(close){world.inspectAngle='side';world.zoom=1.25;}resetJoy();state.position={x:-.8,z:4.5};motion.vx=motion.vz=motion.speed=0;motion.yaw=Math.PI/2;world.player.rotation.y=motion.yaw;world.worker.reset();world.lockValidationCamera=!close;world.validationCamera=null;active=true;time=0;frames=0;stages=[];lastStage='';started=performance.now();lastPos={...state.position};button.disabled=true;panel.querySelector('#runCandidateClose').disabled=true;link.hidden=true;link.style.display='none';chunks=[];for(const k in visits)delete visits[k];document.querySelector('#objective')?.classList.add('hidden');try{const canvas=world.renderer.domElement,stream=canvas.captureStream(20);recorder=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm',videoBitsPerSecond:3000000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob(chunks,{type:'video/webm'}));link.href=url;link.hidden=false;link.style.display='block';stream.getTracks().forEach(t=>t.stop());};recorder.start(500);}catch(e){recorder=null;} }
 function finish(){active=false;setInspect(false);world.inspectAngle=previousAngle;world.lockValidationCamera=false;button.disabled=false;panel.querySelector('#runCandidateClose').disabled=false;button.textContent='Repetir prueba';if(recorder?.state==='recording')recorder.stop();const data={hotfix:3,camera:closeView?'Inspección cercana, fija':'Cámara habitual, fija',model:world.worker.stats,stages,statesSeen:visits,metrics:world.worker.metrics,durationSeconds:(performance.now()-started)/1000,simulationUpdatesPerSecond:frames/((performance.now()-started)/1000),renderer:world.renderer.isSoftwareRenderer?'Canvas 2D compatible':'WebGL2',note:'Prueba de integración. Sin anclajes mundiales de pies. Turn es una adaptación corta de la caminata, no captura de un pivote dedicado.'};panel.querySelector('#candidateReport').textContent=JSON.stringify(data,null,2);panel.querySelector('details').hidden=false;status.innerHTML='<b style="color:#6de5cc">Prueba terminada</b><br>Reposo, marcha, giro, frenado<br>y cambios continuos de dirección.';}
 function input(dt){if(!active)return null;time+=dt;frames++;if(closeView&&time>1.6)world.lockValidationCamera=true;const observed=world.worker.state;visits[observed]=(visits[observed]||0)+1;let stage,x=0,z=0;if(time<2)stage='Quieto';else if(time<4.3){stage='Caminar';x=1;}else if(time<5.4)stage='Frenar';else if(time<6.7){stage='Girar 180°';x=-.04;}else if(time<9){stage='Regresar';x=-1;}else if(time<10)stage='Detenerse';else if(time<15){stage='Joystick circular';const a=(time-10)*1.8;x=Math.sin(a)*.55;z=Math.cos(a)*.55;}else if(time<17)stage='Reposo final';else{finish();return{x:0,z:0};}if(stage!==lastStage){stages.push({stage,time:Number(time.toFixed(3)),position:{...state.position},distance:world.worker.metrics.distance});lastStage=stage;}if(frames%4===0)status.textContent=stage+' · '+world.worker.state+'\n'+motion.speed.toFixed(2)+' m/s · '+world.worker.metrics.distance.toFixed(2)+' m';status.style.whiteSpace='pre-line';return{x,z};}
 button.onclick=()=>begin(false);panel.querySelector('#runCandidateClose').onclick=()=>begin(true);if(new URLSearchParams(location.search).get('hotfix3')==='auto')setTimeout(begin,800);return{input,get active(){return active;}};
}
